   4 import { convertMarkdownToWord } from '@/lib/markdown-to-word-converter';
   5 import type { ProjectProperties } from '@/lib/types';
   6 import type { ConversionOptions } from '@/modules/ai-content/infrastructure/exporters/word-converter/types';
   7 import { NextRequest, NextResponse } from 'next/server';
   8 import { z } from 'zod';
   9 
  10 const projectExportSchema = z.object({
  11   project: z.any().refine(val => val && typeof val === 'object' && val.id, { message: "Project object is invalid." }),
  12   selectedContent: z.array(z.any()),
  13   options: z.custom<ConversionOptions>().optional().default({}),
  14 });
  15 
  16 const markdownExportSchema = z.object({
  17   markdown: z.string().min(1),
  18   fileName: z.string().min(1),
  19   options: z.custom<ConversionOptions>().optional().default({}),
  20 });
  21 
  22 const exportSchema = z.union([projectExportSchema, markdownExportSchema]);
  23 
  24 
  25 export async function POST(req: NextRequest) {
  26   try {
  27     const body = await req.json();
  28     const validation = exportSchema.safeParse(body);
  29 
  30     if (!validation.success) {
  31       return new NextResponse(JSON.stringify(validation.error.flatten()), { status: 400 });
  32     }
  33 
  34     let docxBuffer: Buffer | Blob;
  35     let fileName: string;
  36 
  37     if ('project' in validation.data) {
  38         // Handle project-based export
  39         // Note: We pass the plain data objects instead of instantiating classes
  40         // because Project/Chapter/Section are client components
  41         const { project: projectData, selectedContent: selectedContentData, options } = validation.data;
  42         
  43         // Pass data directly to converter - it will handle the conversion
  44         docxBuffer = await convertMarkdownToWord(
  45           projectData as any, 
  46           { 
  47             ...options, 
  48             selectedContent: selectedContentData as any 
  49           }
  50         );
  51         fileName = `${(projectData as ProjectProperties).name?.replace(/\s+/g, '_') || 'document'}.docx`;
  52 
  53     } else {
  54         // Handle direct markdown export
  55         const directData = validation.data as { markdown: string; fileName: string; options: ConversionOptions };
  56         docxBuffer = await convertMarkdownToWord(directData.markdown, directData.fileName, directData.options);
  57         fileName = `${directData.fileName}.docx`;
  58     }
  59 
  60     if (!docxBuffer) {
  61       return new NextResponse('Error creating DOCX file buffer.', { status: 500 });
  62     }
  63 
  64     return new NextResponse(docxBuffer as any, {
  65       status: 200,
  66       headers: {
  67         'Content-Type': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  68         'Content-Disposition': `attachment; filename="${fileName}"`,
  69       },
  70     });
  71 
  72   } catch (error) {
  73     console.error('DOCX Export API Error:', error);
  74     const errorMessage = error instanceof Error ? error.message : 'Unknown error';
  75     const errorStack = error instanceof Error ? error.stack : undefined;
  76     
  77     // Log detailed error for debugging
  78     console.error('Error details:', {
  79       message: errorMessage,
  80       stack: errorStack,
  81       type: error instanceof Error ? error.constructor.name : typeof error
  82     });
  83     
  84     return new NextResponse(
  85       JSON.stringify({ 
  86         message: 'Error converting to .docx file.', 
  87         error: errorMessage,
  88         details: process.env.NODE_ENV === 'development' ? errorStack : undefined
  89       }), 
  90       { 
  91         status: 500,
  92         headers: { 'Content-Type': 'application/json' }
  93       }
  94     );
  95   }
  96 }
