 416 /**
 417  * Converts a Project object (or plain project data) or a raw markdown string to a styled .docx file.
 418  * This is the main server-side function for DOCX generation.
 419  * 
 420  * Note: Accepts both Project instances and plain project data objects to support
 421  * server-side rendering where client components cannot be instantiated.
 422  */
 423 export async function convertMarkdownToWord(
 424   projectOrMarkdown: Project | any | string,
 425   optionsOrFileName?: (ConversionOptions & { selectedContent?: ProjectContent }) | string,
 426   optionsForMarkdown: ConversionOptions = {}
 427 ): Promise<Buffer | Blob> {
 428   try {
 429     // Input validation
 430     if (!projectOrMarkdown) {
 431       throw new Error('Input is required: provide either a Project object or markdown string');
 432     }
 433 
 434     // Check if input is a Project-like object (either instance or plain object)
 435     if (typeof projectOrMarkdown === 'object' && projectOrMarkdown !== null && 'content' in projectOrMarkdown) {
 436       // Handle Project object or plain project data
 437       const project = projectOrMarkdown as any;
 438       const options = (optionsOrFileName as (ConversionOptions & { selectedContent?: ProjectContent })) || {};
 439       const { styles, selectedContent, coverPageMarkdown: explicitCoverPage } = options;
 440 
 441       const finalStyles: IStylesOptions = {
 442         ...styles,
 443         paragraphStyles: [...(styles?.paragraphStyles || [])],
 444       };
 445 
 446       const captionStyleExists = finalStyles.paragraphStyles!.some(style => style.id === 'Caption');
 447       if (!captionStyleExists) {
 448         (finalStyles.paragraphStyles as any).push({
 449           id: 'Caption',
 450           name: 'Caption',
 451           basedOn: 'Normal',
 452           next: 'Normal',
 453           quickFormat: true,
