   0 /**
   1  * Document Indexing Service
   2  * 
   3  * This module handles indexing documents into the vector store.
   4  * It chunks documents, generates embeddings, and stores them.
   5  */
   6 
   7 import { chunkText, generateEmbeddings } from './embeddings';
   8 import { getVectorStore, type DocumentChunk } from './vector-store';
   9 import { v4 as uuidv4 } from 'uuid';
  10 
  11 export interface IndexingOptions {
  12   projectId?: string;
  13   userId?: string;
  14   sourceFile?: string;
  15   chunkSize?: number;
  16   overlap?: number;
  17   type?: 'report' | 'reference' | 'context' | 'user_upload';
  18 }
  19 
  20 export interface IndexingResult {
  21   success: boolean;
  22   chunksCreated: number;
  23   errors?: string[];
  24 }
  25 
  26 /**
  27  * Index a document into the vector store
  28  */
  29 export async function indexDocument(
  30   content: string,
  31   options: IndexingOptions = {}
  32 ): Promise<IndexingResult> {
  33   const {
  34     projectId,
  35     userId,
  36     sourceFile,
  37     chunkSize = 500,
  38     overlap = 50,
  39     type = 'context',
  40   } = options;
  41 
  42   const errors: string[] = [];
  43 
  44   try {
  45     // 1. Split document into chunks
  46     const textChunks = chunkText(content, {
  47       chunkSize,
  48       overlap,
  49       preserveParagraphs: true,
  50     });
  51 
  52     console.log(`Split document into ${textChunks.length} chunks`);
  53 
  54     // 2. Generate embeddings for all chunks
  55     let embeddings: number[][];
  56     try {
  57       embeddings = await generateEmbeddings(textChunks);
  58     } catch (error) {
  59       errors.push(`Failed to generate embeddings: ${error instanceof Error ? error.message : 'Unknown error'}`);
  60       return {
  61         success: false,
  62         chunksCreated: 0,
  63         errors,
  64       };
  65     }
  66 
  67     // 3. Create document chunks with embeddings
  68     const documentChunks: DocumentChunk[] = textChunks.map((chunk, idx) => ({
  69       id: uuidv4(),
  70       content: chunk,
  71       embedding: embeddings[idx],
  72       metadata: {
  73         projectId,
  74         userId,
  75         sourceFile,
  76         chunkIndex: idx,
  77         timestamp: Date.now(),
  78         type,
  79       },
  80     }));
  81 
  82     // 4. Add chunks to vector store
  83     const vectorStore = getVectorStore();
  84     await vectorStore.addChunks(documentChunks);
  85 
  86     console.log(`Successfully indexed ${documentChunks.length} chunks`);
  87 
  88     return {
  89       success: true,
  90       chunksCreated: documentChunks.length,
  91     };
  92   } catch (error) {
  93     console.error('Error indexing document:', error);
  94     errors.push(error instanceof Error ? error.message : 'Unknown error');
  95     
  96     return {
  97       success: false,
  98       chunksCreated: 0,
  99       errors,
 100     };
 101   }
 102 }
