 115 /**
 116  * Index project context (sections, chapters, etc.)
 117  * This is called when a report is generated to make it available for RAG
 118  */
 119 export async function indexProjectContext(
 120   projectId: string,
 121   userId: string,
 122   context: {
 123     sections?: Array<{ title: string; content: string }>;
 124     chapters?: Array<{ title: string; content: string }>;
 125     otherDocuments?: Array<{ title: string; content: string }>;
 126   }
 127 ): Promise<IndexingResult> {
 128   const documents: Array<{ content: string; options: IndexingOptions }> = [];
 129 
 130   // Add sections
 131   if (context.sections) {
 132     context.sections.forEach(section => {
 133       documents.push({
 134         content: `# ${section.title}\n\n${section.content}`,
 135         options: {
 136           projectId,
 137           userId,
 138           sourceFile: `Section: ${section.title}`,
 139           type: 'report',
 140         },
 141       });
 142     });
 143   }
 144 
 145   // Add chapters
 146   if (context.chapters) {
 147     context.chapters.forEach(chapter => {
 148       documents.push({
 149         content: `# ${chapter.title}\n\n${chapter.content}`,
 150         options: {
 151           projectId,
 152           userId,
 153           sourceFile: `Chapter: ${chapter.title}`,
 154           type: 'report',
 155         },
 156       });
 157     });
 158   }
 159 
 160   // Add other documents
 161   if (context.otherDocuments) {
 162     context.otherDocuments.forEach(doc => {
 163       documents.push({
 164         content: `# ${doc.title}\n\n${doc.content}`,
 165         options: {
 166           projectId,
 167           userId,
 168           sourceFile: doc.title,
 169           type: 'context',
 170         },
 171       });
 172     });
 173   }
 174 
 175   const results = await indexDocuments(documents);
 176 
 177   // Aggregate results
 178   const totalChunks = results.reduce((sum, r) => sum + r.chunksCreated, 0);
 179   const allErrors = results.flatMap(r => r.errors || []);
 180 
 181   return {
 182     success: results.every(r => r.success),
 183     chunksCreated: totalChunks,
 184     errors: allErrors.length > 0 ? allErrors : undefined,
 185   };
 186 }
